css='''*{box-sizing:border-box}body{margin:0;font:13px/1.45 -apple-system,BlinkMacSystemFont,system-ui,sans-serif;color:#1d1d1f}main{max-width:890px;margin:0 auto;padding:28px 24px}h1{font-size:26px;letter-spacing:-.7px;margin:0}p{margin:6px 0 16px}h2{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#6a6a70;margin:28px 0 12px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:24px}.theme{--control-edge:#85858e;--surface:#fff;--canvas:#f6f6f7;--text:#1d1d1f;--secondary:#63636b;--edge:#d2d2d8;--fill:#f0f0f3;--blue:#0066d6;--tint:#e8f2ff;--good:#1d8036;color:var(--text);background:var(--canvas);padding:18px;border-radius:16px;min-width:0}.dark{--surface:#242426;--canvas:#19191b;--text:#f5f5f7;--secondary:#b5b5bd;--edge:#505056;--fill:#333337;--blue:#80b8ff;--tint:#293b55;--good:#82d99a;color-scheme:dark}.mode{font-size:11px;color:var(--secondary);margin-bottom:12px;font-weight:600}.panel{background:var(--surface);border:1px solid var(--edge);border-radius:12px;overflow:hidden;box-shadow:0 8px 24px #0000000c;max-width:360px;margin:auto}.head{display:flex;gap:8px;align-items:center;padding:14px 16px;border-bottom:1px solid var(--edge);font-weight:600}.head img{width:22px;height:22px}.head small{margin-left:auto;color:var(--secondary);font-weight:400}.body{padding:16px}.site{font-size:12px;color:var(--secondary);margin-bottom:12px}.group-label{font-size:11px;font-weight:600;color:var(--secondary);letter-spacing:.04em;text-transform:uppercase;margin:14px 0 7px}.account{display:flex;align-items:center;gap:10px;text-align:left;width:100%;border:0;background:transparent;padding:10px 8px;border-radius:8px;min-height:58px}.account:hover{background:var(--tint)}.account .text{min-width:0;flex:1}.account strong,.account small{display:block;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.account small{font-size:12px;color:var(--secondary);margin-top:2px}.avatar{width:32px;height:32px;background:var(--fill);border:1px solid var(--edge);border-radius:8px;display:grid;place-items:center;font-weight:600;color:var(--secondary)}button,input{font:inherit;color:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible{outline:2px solid var(--blue);outline-offset:3px}.primary,.secondary{min-height:34px;padding:7px 12px;border-radius:7px;font-weight:500}.primary{background:#0066d6;border:1px solid #0066d6;color:#fff}.dark .primary{background:#80b8ff;border-color:#80b8ff;color:#10233a}.secondary{background:var(--surface);border:1px solid var(--control-edge)}.text-button{border:0;background:transparent;color:var(--blue);padding:6px 0}.bottom{padding:10px 16px;background:var(--canvas);border-top:1px solid var(--edge);display:flex;justify-content:space-between;align-items:center;color:var(--secondary);font-size:12px}.bottom button{font-size:12px}.tools{display:flex;gap:8px;border-top:1px solid var(--edge);padding-top:12px;margin-top:12px}.tools>*{flex:1}.help{color:var(--secondary);font-size:12px;margin:12px 0 0}.center{text-align:center;padding:30px 22px}.center h3{font-size:17px;letter-spacing:-.2px;margin:12px 0 8px}.center p{color:var(--secondary);margin-bottom:18px}.center img{width:40px;height:40px;border-radius:10px}.center .primary{width:100%}input[type=search],input[type=text],input[type=email],input[type=password],input[type=number]{width:100%;border:1px solid var(--control-edge);background:var(--canvas);border-radius:7px;padding:8px 10px;min-height:36px}label{display:block;color:var(--secondary);font-size:12px;margin-bottom:12px}label input{display:block;margin-top:5px;color:var(--text)}.split{display:flex;gap:12px;align-items:center}.split label{flex:1}.check{display:flex;gap:8px;align-items:center}.check input{margin:0}.subtitle{font-size:16px;margin:0 0 14px}.login-site{position:relative;min-height:440px;padding:20px 4px}.login-site h3{font-size:20px;margin:0 0 18px}.inline{position:absolute;top:127px;left:0;right:0;z-index:3}.inline .head{padding:10px 12px}.inline .body{padding:8px}.inline .account{min-height:58px}.field-icon{position:absolute;right:14px;top:86px;width:24px;height:24px;border:0;padding:2px;background:var(--surface);border-radius:5px}.field-icon img{width:20px;height:20px}.banner{padding:16px}.banner .identity{display:flex;gap:10px;align-items:center}.banner img{width:28px;height:28px}.banner strong{display:block}.banner small{color:var(--secondary)}.banner .tools{border:0;margin:12px 0 0;padding:0}.waiting{padding:22px 20px}.waiting .status{font-size:11px;letter-spacing:.06em;color:var(--blue);font-weight:600}.waiting h3{font-size:18px;margin:10px 0}.waiting p{color:var(--secondary)}.context{padding:12px;background:var(--canvas);border:1px solid var(--edge);border-radius:8px;margin:18px 0}.context small{display:block;color:var(--secondary)}.notice{min-height:18px;font-size:12px;color:var(--good);margin-top:8px}.hint-key{border:1px solid var(--edge);padding:0 4px;border-radius:3px}.badge{color:var(--good);font-size:12px}.theme [hidden]{display:none}@media(max-width:700px){main{padding:16px 8px}.pair{gap:10px}.theme{padding:10px}.head{padding:12px 10px}.head small{font-size:10px}.body{padding:12px}.center{padding:20px 12px}}@media(prefers-reduced-motion:no-preference){button{transition:background 120ms ease}}'''
head=f'<div class="head"><img src="data:image/png;base64,{icon}" alt=""><span>Apassy</span><small>github.com</small></div>'
foot='<div class="bottom"><span>Connected to your Mac</span><button class="text-button settings">Settings</button></div>'
def panel(content):return '<div class="panel">'+head+content+foot+'</div>'
def account(title,user):return f'<button class="account fill"><span class="avatar">{title[0]}</span><span class="text"><strong>{title}</strong><small>{user}</small></span><span style="color:var(--blue)">Fill</span></button>'
items=account('Personal','alex@example.test')+account('Work','alex.work@example.test')
states=[('01 · Popup / matching logins',panel('<div class="body"><input type="search" aria-label="Filter accounts for github.com" placeholder="Find an account for this site"><div class="group-label">2 accounts for this site</div><div class="accounts">'+items+'</div><p class="help">Choose an account, then approve on your Mac.</p><div class="tools"><button class="secondary save">Save login</button><button class="secondary generate">New password</button></div><div class="notice" role="status"></div></div>')),
('02 · Popup / no matching login',panel(f'<div class="center"><img src="data:image/png;base64,{icon}" alt=""><h3>No logins for github.com</h3><p>Save the login you entered on this page, or create a password for a new account.</p><button class="primary save">Save this login</button><button class="text-button generate">Create a new password</button><p class="help">Already saved? Check its Website in Apassy.</p><div class="notice" role="status"></div></div>')),
('03 · Popup / locked vault',panel(f'<div class="center"><img src="data:image/png;base64,{icon}" alt=""><h3>Your vault is locked</h3><p>Open Apassy on your Mac to unlock it. Then return here to choose an account.</p><button class="primary open">Open Apassy</button><p class="help">Each fill still needs your approval.</p><div class="notice" role="status"></div></div>')),
('04 · Popup / create and save password',panel('<form class="body generator"><h3 class="subtitle">New login for github.com</h3><label>Title<input type="text" value="GitHub" required></label><label>Username<input type="email" value="alex@example.test" required></label><div class="split"><label>Password length<input type="number" min="12" max="64" value="20" required></label><label class="check"><input type="checkbox" checked>Use symbols</label></div><p class="help">Approve on your Mac. Apassy saves the password before filling this page.</p><div class="tools"><button class="secondary back" type="button">Back</button><button class="primary" type="submit">Create and fill</button></div><div class="notice" role="status"></div></form>')),
('05 · Inline / isolated account menu','<div class="login-site"><h3>Sign in to Example</h3><label>Email<input type="email" value="" placeholder="you@example.com"></label><button class="field-icon" aria-label="Show Apassy accounts"><img src="data:image/png;base64,'+icon+'" alt=""></button><label>Password<input type="password" placeholder="Password"></label><button class="secondary">Sign in</button><div class="panel inline"><div class="head"><img src="data:image/png;base64,'+icon+'" alt=""><span>Apassy</span><small>example.com</small></div><div class="body">'+items+'<p class="help">Your Mac asks for approval before filling.</p><div class="notice" role="status"></div></div><div class="bottom"><span><span class="hint-key">↑</span> <span class="hint-key">↓</span> to choose</span><button class="text-button dismiss">Dismiss · Esc</button></div></div></div>'),
('06 · After submit / proposed save offer','<div class="panel banner"><div class="identity"><img src="data:image/png;base64,'+icon+'" alt=""><div><strong>Save this login in Apassy?</strong><small>example.com · alex@example.test</small></div></div><p class="help">Saving needs your approval on your Mac.</p><div class="tools"><button class="secondary dismiss">Not now</button><button class="primary save">Save login</button></div><div class="notice" role="status"></div></div>'),
('07 · Approval / waiting on your Mac','<div class="panel waiting"><span class="status">WAITING FOR APPROVAL</span><h3>Check Touch ID on your Mac</h3><p>Approve in Apassy to fill this login. If asked, use your vault passphrase.</p><div class="context"><strong>github.com</strong><small>Personal · alex@example.test</small></div><p class="help">Nothing has been filled yet.</p><button class="secondary open">Show Apassy</button><div class="notice" role="status"></div></div>')]
body='<main><h1>Apassy, at the point of use.</h1><p>Extension redesign · Light and dark · Interactive design study</p>'
for title,content in states:
 body+=f'<h2>{title}</h2><div class="pair"><section class="theme"><div class="mode">LIGHT</div>{content}</section><section class="theme dark"><div class="mode">DARK</div>{content}</section></div>'
body+='</main>'
js='''document.querySelectorAll('input[type=search]').forEach(input=>input.addEventListener('input',()=>{input.closest('.body').querySelectorAll('.account').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(input.value.toLowerCase()))}));document.querySelectorAll('button.fill,button.save,button.open,button.generate,button.back,button.settings').forEach(b=>b.addEventListener('click',()=>{const scope=b.closest('.panel')||b.closest('.theme');const n=scope.querySelector('.notice');if(n)n.textContent=b.classList.contains('fill')?'Demo: approval is required on your Mac. No password is present.':b.classList.contains('save')?'Demo: review this login and approve saving on your Mac.':b.classList.contains('open')?'Demo: Apassy would open on your Mac.':b.classList.contains('generate')?'See the New login study below.':b.classList.contains('settings')?'Site suggestions and browser passkeys belong in Settings.':'Demo: return to accounts.'}));document.querySelectorAll('form.generator').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();f.querySelector('.notice').textContent='Demo: waiting for approval on your Mac. No password generated.'}));document.querySelectorAll('.dismiss').forEach(b=>b.addEventListener('click',()=>b.closest('.panel').hidden=true));document.querySelectorAll('.field-icon').forEach(b=>b.addEventListener('click',()=>b.parentElement.querySelector('.inline').hidden=false));document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.inline').forEach(p=>p.hidden=true)});'''
body=body.replace('src="data:image/png;base64,'+icon+'"','data-brand')
js="document.querySelectorAll('img[data-brand]').forEach(i=>i.src='data:image/png;base64,"+icon+"');"+js
hash=base64.b64encode(hashlib.sha256(js.encode()).digest()).decode();html=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; img-src data:; style-src \'unsafe-inline\'; script-src \'sha256-{hash}\'"><title>Apassy extension redesign</title><style>{css}</style></head><body>{body}<script>{js}</script></body></html>'
(out/'extension-redesign-mockup.html').write_text(html)
